// ════════════════════════════════════════════════════════════
//  == FUNCTION NODE: UNIFIER v5.4 ==
//  Változás v5.3-hoz képest:
//  - "gateway" típus kezelése: DIRIGERA HUB adatok (nextSunSet, nextSunRise, homestate)
//  - "motion" típus kezelése: mozgásérzékelő (detected, room, battery)
//  Új state ágak: state.gateway, state.motion
// ════════════════════════════════════════════════════════════

function quickHash(obj) {
    const s = JSON.stringify(obj);
    let h = 0;
    for (let i = 0; i < s.length; i++) {
        h = (Math.imul(31, h) + s.charCodeAt(i)) | 0;
    }
    return h;
}

function getState() {
    const s = global.get("dash_state") || {};
    if (!s.weather)  s.weather = null;
    if (!s.ac)       s.ac = null;
    if (!s.sensors)  s.sensors = {};
    if (!s.sensors.th)       s.sensors.th = {};
    if (!s.sensors.switches) s.sensors.switches = {};
    if (!s.sensors.shutters) s.sensors.shutters = {};
    if (!s.lights)   s.lights = {};
    if (!s.lights.bulbs)       s.lights.bulbs = {};
    if (!s.lights.controllers) s.lights.controllers = {};
    if (!s.gateway)  s.gateway = null;   // ÚJ: DIRIGERA HUB
    if (!s.motion)   s.motion = {};      // ÚJ: mozgásérzékelők
    if (!s._hash)    s._hash = null;
    return s;
}

// ── Sonoff mapping ───────────────────────────────────────────
const SONOFF_FOR_LIGHT = {
    "nappali":          [{ room: "nappali",  label: "Nappali" }],
    "lego_vitrin":      [{ room: "nappali",  label: "Dolgozó" }],
    "dolgozo_spot_1":   [{ room: "nappali",  label: "Dolgozó" }],
    "dolgozo_spot_2":   [{ room: "nappali",  label: "Dolgozó" }],
    "dolgozo_spot_3":   [{ room: "nappali",  label: "Dolgozó" }],
    "konyha_spot_1":    [{ room: "eloszoba", label: "Konyha" }],
    "konyha_spot_2":    [{ room: "eloszoba", label: "Konyha" }],
    "konyha_spot_3":    [{ room: "eloszoba", label: "Konyha" }],
    "konyha_spot_4":    [{ room: "eloszoba", label: "Konyha" }],
    "konyhabutor":      [{ room: "eloszoba", label: "Konyha" }],
    "konyhabutor_fiok": [{ room: "eloszoba", label: "Konyha" }],
    "halo_01":          [{ room: "halo",     label: "Háló 1" }, { room: "halo", label: "Háló 2" }],
    "halo_02":          [{ room: "halo",     label: "Háló 1" }, { room: "halo", label: "Háló 2" }],
    "gyerek":           [{ room: "gyerek",   label: "Gyerekszoba" }],
    "eloszoba_bulb_1":  [{ room: "eloszoba", label: "Előszoba" }],
    "eloszoba_bulb_2":  [{ room: "eloszoba", label: "Előszoba" }],
    "eloszoba_bulb_3":  [{ room: "eloszoba", label: "Előszoba" }],
    "technika":         []   // folyamatos áram
};

function isSonoffOn(sonoffList, switchMap) {
    if (sonoffList.length === 0) return true;
    return sonoffList.some(sw => switchMap[sw.room] && switchMap[sw.room][sw.label] === true);
}

// ════════════════════════════════════════════════════════════
//  FŐLOGIKA
// ════════════════════════════════════════════════════════════
const state = getState();
const p = msg.payload;
const receivedAt = Date.now();
state._updated = state._updated || {};
state._updated.th = state._updated.th || {};
state._updated.switches = state._updated.switches || {};

if (p && !Array.isArray(p) && p.type === "weather") {
    const { type, ...data } = p;
    state.weather = data;
    state._updated.weather = receivedAt;
}
else if (p && !Array.isArray(p) && p.type === "ac") {
    const { type, ...data } = p;
    state.ac = data;
    state._updated.ac = receivedAt;
}
else if (Array.isArray(p)) {
    const items = p.flatMap(x => Array.isArray(x) ? x : [x]);

    items.forEach(item => {
        if (!item || !item.type) return;

        switch (item.type) {

            case "th":
                state._updated.th[item.room] = receivedAt;
                state.sensors.th[item.room] = {
                    temp:    item.temp,
                    hum:     item.hum,
                    battery: item.battery,
                    online:  item.online
                };
                break;

            case "switch":
                state._updated.switches[item.room] = state._updated.switches[item.room] || {};
                state._updated.switches[item.room][item.label] = receivedAt;
                if (!state.sensors.switches[item.room]) state.sensors.switches[item.room] = {};
                state.sensors.switches[item.room][item.label] = item.state;
                break;

            case "shutter": {
                if (!state.sensors.shutters[item.room]) state.sensors.shutters[item.room] = {};
                const prev = state.sensors.shutters[item.room][item.label] || {};
                state.sensors.shutters[item.room][item.label] = {
                    pct:   (item.pct   != null) ? item.pct   : (prev.pct   ?? null),
                    motor: (item.motor != null) ? item.motor : (prev.motor ?? null)
                };
                break;
            }

            case "light": {
                const sonoffList = SONOFF_FOR_LIGHT[item.label] ?? null;
                const sonoffOn = sonoffList === null
                    ? item.reachable
                    : isSonoffOn(sonoffList, state.sensors.switches);
                const isOn = sonoffOn && item.reachable === true && item.on === true;

                if (!state.lights.bulbs[item.room]) state.lights.bulbs[item.room] = {};
                state.lights.bulbs[item.room][item.label] = {
                    on:        isOn,
                    level:     item.level,
                    reachable: item.reachable,
                    sonoffOn:  sonoffOn,
                    ...(item.hue !== undefined ? { hue: item.hue, sat: item.sat, ct: item.ct } : {})
                };
                break;
            }

            case "controller":
                state.lights.controllers[item.label] = {
                    battery:   item.battery,
                    reachable: item.reachable
                };
                break;

            // ── ÚJ: DIRIGERA HUB ────────────────────────────
            case "gateway":
                state.gateway = {
                    reachable:        item.reachable,
                    backendConnected: item.backendConnected,
                    homestate:        item.homestate,
                    nextSunSet:       item.nextSunSet,
                    nextSunRise:      item.nextSunRise,
                    timezone:         item.timezone,
                    firmwareVersion:  item.firmwareVersion
                };
                break;

            // ── ÚJ: MOZGÁSÉRZÉKELŐ ──────────────────────────
            case "motion": {
                // room-kulcs: a dirigera "Technika" szobanévből → "technika"
                const roomKey = (item.room || item.label || "unknown")
                    .toLowerCase()
                    .normalize("NFD")
                    .replace(/[\u0300-\u036f]/g, "")
                    .trim();
                state.motion[roomKey] = {
                    detected:  item.detected,
                    reachable: item.reachable,
                    battery:   item.battery,
                    label:     item.label
                };
                break;
            }
        }
    });
}

const newHash = quickHash({
    w: state.weather,
    a: state.ac,
    s: state.sensors,
    l: state.lights,
    g: state.gateway,
    m: state.motion
});

if (!msg.injected && newHash === state._hash) return null;

state._hash = newHash;
state._ts = receivedAt;
global.set("dash_state", state);

return {
    payload: {
        weather: state.weather,
        ac:      state.ac,
        sensors: state.sensors,
        lights:  state.lights,
        gateway: state.gateway,
        motion:  state.motion,
        _ts:     state._ts,
        _updated: state._updated
    }
};

// ════════════════════════════════════════════════════════════
//  == FUNCTION NODE: normalize_weather ==
//  Elhelyezés: HTTP request (Open-Meteo) után
//  Trigger: inject 15 percenként
// ════════════════════════════════════════════════════════════

msg.injected = true; // inject triggerelte

const raw = msg.payload;
const c   = raw.current;
const d   = raw.daily;
const h   = raw.hourly;

const idx   = h.time.findIndex(t => t === c.time);
const start = idx >= 0 ? idx : 0;

const forecast = [];
for (let i = 0; i < 8; i++) {
    const j = start + i;
    if (j >= h.time.length) break;
    forecast.push({
        time: h.time[j],
        temp: h.temperature_2m[j],
        pop:  h.precipitation_probability[j],
        code: h.weather_code[j]
    });
}

msg.payload = {
    type:      "weather",
    time:      c.time,
    temp:      c.temperature_2m,
    humidity:  c.relative_humidity_2m,
    code:      c.weather_code,
    wind:      c.wind_speed_10m,
    gust:      c.wind_gusts_10m,
    tempMax:   d.temperature_2m_max[0],
    tempMin:   d.temperature_2m_min[0],
    sunrise:   d.sunrise[0].slice(11, 16),
    sunset:    d.sunset[0].slice(11, 16),
    precipSum: d.precipitation_sum[0],
    precipMax: d.precipitation_probability_max[0],
    forecast:  forecast
};

// ── Node status ──────────────────────────────────────────────
const wmoIcons = {
    0: "☀️", 1: "🌤️", 2: "⛅", 3: "☁️",
    45: "🌫️", 48: "🌫️",
    51: "🌦️", 53: "🌦️", 55: "🌧️",
    61: "🌧️", 63: "🌧️", 65: "🌧️",
    71: "🌨️", 73: "🌨️", 75: "❄️",
    80: "🌦️", 81: "🌧️", 82: "⛈️",
    95: "⛈️", 96: "⛈️", 99: "⛈️"
};

const icon = wmoIcons[msg.payload.code] ?? "🌡️";
const t    = msg.payload.temp;
const hum  = msg.payload.humidity;
const wind = msg.payload.wind;

node.status({
    fill:  t > 30 ? "red" : t > 20 ? "yellow" : t > 10 ? "green" : "blue",
    shape: "dot",
    text:  `${icon} ${t}°C  💧${hum}%  💨${wind}km/h`
});

return msg;

// ════════════════════════════════════════════════════════════
//  == FUNCTION NODE: normalize_th ==
//  Elhelyezés: iHost get-devices (T&H sensors, all) után
//  Trigger: inject 30 másodpercenként
//  A node "all devices" módban adja vissza az összes T&H szenzort
// ════════════════════════════════════════════════════════════

msg.injected = true; // inject triggerelte

const ROOM_MAP = {
    "Nappali T&H":     "nappali",
    "Hálószoba T&H":   "halo",
    "Gyerekszoba T&H": "gyerek",
    "Fürdőszoba T&H":  "furdo",
    "WC T&H":          "wc"
};

const devices = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
const out = [];

devices.forEach(dev => {
    const room = ROOM_MAP[dev.name];
    if (!room) return;
    out.push({
        type:    "th",
        room:    room,
        temp:    dev.state.temperature?.temperature ?? null,
        hum:     dev.state.humidity?.humidity ?? null,
        battery: dev.state.battery?.battery ?? null,
        online:  dev.online
    });
});

msg.payload = out;

// ── Node status ──────────────────────────────────────────────
const sensors = msg.payload;

const offline  = sensors.filter(s => !s.online);
const lowBat   = sensors.filter(s => s.battery !== null && s.battery < 20);
const total    = sensors.length;
const online   = sensors.filter(s => s.online).length;

if (total === 0) {
    node.status({ fill: "red", shape: "ring", text: "⚠️ Nincs szenzor" });
    return msg;
}

if (offline.length > 0) {
    const names = offline.map(s => s.room).join(", ");
    node.status({ fill: "red", shape: "ring", text: `⚠️ Offline: ${names}` });
    return msg;
}

if (lowBat.length > 0) {
    const names = lowBat.map(s => `${s.room}(${s.battery}%)`).join(", ");
    node.status({ fill: "yellow", shape: "dot", text: `🪫 ${names}` });
    return msg;
}

// Minden OK → átlagok mutatása
const temps = sensors.filter(s => s.temp !== null).map(s => s.temp);
const hums  = sensors.filter(s => s.hum  !== null).map(s => s.hum);
const avgT  = (temps.reduce((a, b) => a + b, 0) / temps.length).toFixed(1);
const avgH  = Math.round(hums.reduce((a, b) => a + b, 0) / hums.length);

node.status({
    fill:  "green",
    shape: "dot",
    text:  `✅ ${online}/${total}  🌡️ ${avgT}°C  💧${avgH}%`
});

return msg;

// ════════════════════════════════════════════════════════════
//  == FUNCTION NODE: normalize_light_switches ==
//  Elhelyezés: join(6) után — Nappali, Háló, Gyerek, WC, Fürdő, Előszoba
//  Trigger: inject 30 másodpercenként
// ════════════════════════════════════════════════════════════

msg.injected = true;

const TOGGLE_MAP = {
    "00000000-0000-4000-8000-000000000012": { room: "nappali",  ch: { "1":"Dolgozó", "2":"Nappali", "3":"Kültér A" } },
    "00000000-0000-4000-8000-000000000013": { room: "halo",     ch: { "1":"Háló 1", "2":"Háló 2" } },
    "00000000-0000-4000-8000-000000000009": { room: "gyerek",   ch: null },
    "00000000-0000-4000-8000-000000000010": { room: "wc",       ch: null },
    "00000000-0000-4000-8000-000000000011": { room: "furdo",    ch: null },
    "00000000-0000-4000-8000-000000000014": { room: "eloszoba", ch: { "1":"Kültér B", "2":"Előszoba", "3":"Étkező", "4":"Konyha" } }
};

const devices = msg.payload.flat ? msg.payload.flat() : [].concat(...msg.payload);
const outS = [];

devices.forEach(dev => {
    if (!dev || !dev.serial_number) return;
    const map = TOGGLE_MAP[dev.serial_number];
    if (!map) return;

    if (map.ch && dev.state.toggle) {
        Object.entries(dev.state.toggle).forEach(([ch, val]) => {
            const label = map.ch[ch];
            if (!label) return;
            outS.push({ type:"switch", room:map.room, label:label, state: val.toggleState === "on" });
        });
    } else if (dev.state.power) {
        outS.push({ type:"switch", room:map.room, label:dev.name, state: dev.state.power.powerState === "on" });
    }
});

// ── Node status ──────────────────────────────────────────────
const total  = outS.length;
const onList = outS.filter(s => s.state === true);
const on     = onList.length;

if (total === 0) {
    node.status({ fill: "red", shape: "ring", text: "⚠️ Nincs kapcsoló" });
} else if (on === 0) {
    node.status({ fill: "grey", shape: "dot", text: `⏹️ Minden ki (${total})` });
} else {
    const byRoom = {};
    onList.forEach(s => {
        const room = s.room ?? "ismeretlen";
        if (!byRoom[room]) byRoom[room] = 0;
        byRoom[room]++;
    });
    const summary = Object.entries(byRoom)
