// ── DIRIGERA HUB (gateway) ───────────────────────────────────
if (devType === "gateway") {
    msg.payload = [{
        type:             "gateway",
        label:            attrC.customName,
        reachable:        devC.isReachable,
        firmwareVersion:  attrC.firmwareVersion,
        backendConnected: attrC.backendConnected,
        homestate:        attrC.homestate,           // "home" | "away"
        nextSunSet:       attrC.nextSunSet,           // ISO string
        nextSunRise:      attrC.nextSunRise,          // ISO string
        timezone:         attrC.timezone
    }];

    if (!devC.isReachable) {
        node.status({ fill: "red", shape: "ring", text: "🔴 DIRIGERA HUB OFFLINE!" });
    } else {
        const hs = attrC.homestate === "home" ? "🏠" : "🌍";
        node.status({ fill: "green", shape: "dot", text: `🟢 HUB online  ${hs} ${attrC.homestate}` });
    }
    return msg;
}

// ── Motion sensor (occupancySensor) ─────────────────────────
if (devType === "occupancySensor") {
    msg.payload = [{
        type:       "motion",
        label:      attrC.customName,
        room:       devC.room?.name || null,
        reachable:  devC.isReachable,
        detected:   attrC.isDetected,               // true | false
        battery:    attrC.batteryPercentage ?? null
    }];

    const item = msg.payload[0];
    if (!item.reachable) {
        node.status({ fill: "red", shape: "ring", text: `⚠️ Offline: ${item.label}` });
    } else {
        const icon = item.detected ? "🟡 Mozgás!" : "🟢 Csend";
        node.status({ fill: item.detected ? "yellow" : "green", shape: "dot",
                      text: `${icon}  🔋${item.battery ?? "?"}%` });
    }
    return msg;
}

// ── Egyéb kontrollerek (genericSwitch, lightController) ─────
msg.payload = [{
    type:      "controller",
    label:     attrC.customName,
    battery:   attrC.batteryPercentage ?? null,
    reachable: devC.isReachable
}];

const item = msg.payload[0];

if (!item.reachable) {
    node.status({ fill: "red", shape: "ring", text: `⚠️ Offline: ${item.label}` });
} else {
    const bat  = item.battery;
    const fill = bat == null ? "grey" : bat <= 15 ? "red" : bat <= 30 ? "yellow" : "green";
    const icon = bat == null ? "❓" : bat <= 15 ? "🪫" : bat <= 30 ? "⚠️" : "🔋";
    node.status({ fill, shape: "dot", text: `${icon} ${item.label}: ${bat ?? "?"}%` });
}

return msg;

