function toBool(v) {
    if (v === true || v === 1 || v === "1") return true;
    if (v === false || v === 0 || v === "0" || v === null || v === undefined || v === "") return false;
    if (typeof v === "string") {
        const t = v.trim().toLowerCase();
        if (t === "true" || t === "on" || t === "yes") return true;
        if (t === "false" || t === "off" || t === "no") return false;
    }
    return !!v;
}

const raw = Array.isArray(msg.payload) ? msg.payload[0] : msg.payload;

let p = null;
if (raw && raw.Structure && Array.isArray(raw.Structure.Devices) && raw.Structure.Devices.length > 0) {
    p = raw.Structure.Devices[0].Device || null;
}
