    p = raw;
}

if (!p) {
    node.status({ fill: "red", shape: "ring", text: "⚠️ Nincs Device adat" });
    return null;
}

msg.topic = "ac";
msg.payload = {
    buildingId: "1106921",
    deviceId:   "147063004",
    power:    toBool(p.Power),
    roomTemp: Number(p.RoomTemperature),
