    fanSpeed: Number(p.SetFanSpeed),
    modeCode: Number(p.OperationMode),
    vaneH:    p.VaneHorizontal,
    vaneV:    p.VaneVertical,
    pending:  toBool(p.HasPendingCommand),
    offline:  toBool(p.Offline),
    lastCommunication: p.LastCommunication
};

node.status({
    fill: "green", shape: "dot",
    text: `AC: ${p.Power ? "BE" : "ki"} | ${p.RoomTemperature}°→${p.SetTemperature}° | mode ${p.OperationMode}`
